arguments:
$ErrorActionPreference = 'Stop'
$taskName = 'Codex_Install_Cinebench_Cert_20260904T1612'
$scriptPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\Install-CinebenchDigiCertIntermediate-20260904T1610.ps1'
$certificatePath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\DigiCert-Trusted-G4-CodeSigning-2021-CA1-7B0F360B.cer'
$outputPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\cinebench-song-cert-install-20260904T1612.json'
$user = 'DESKTOP-5OJC3K4\Song'
if (Test-Path -LiteralPath $outputPath) { throw ('Refusing to overwrite: ' + $outputPath) }
$quote = [char]34
$arguments = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File ' + $quote + $scriptPath + $quote + ' -CertificatePath ' + $quote + $certificatePath + $quote + ' -OutputPath ' + $quote + $outputPath + $quote
$action = New-ScheduledTaskAction -Execute 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -Argument $arguments
$principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
$settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 3) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
try {
 Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force | Out-Null
 Start-ScheduledTask -TaskName $taskName
 $deadline = (Get-Date).AddSeconds(120)
 while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $outputPath -PathType Leaf)) { Start-Sleep -Seconds 1 }
 if (-not (Test-Path -LiteralPath $outputPath -PathType Leaf)) {
  $info = Get-ScheduledTaskInfo -TaskName $taskName
  throw ('Install output was not created. LastTaskResult=' + $info.LastTaskResult)
 }
 Start-Sleep -Seconds 2
 $result = Get-Content -LiteralPath $outputPath -Raw -Encoding UTF8 | ConvertFrom-Json
 [pscustomobject]@{Identity=$result.Identity;SessionId=$result.SessionId;CertificateStore=$result.CertificateStore;PresentBefore=$result.PresentBefore;Action=$result.Action;PresentAfter=$result.PresentAfter;AllSignaturesValid=$result.AllSignaturesValid;CertificateThumbprint=$result.CertificateThumbprint} | Format-List
 $result.SignatureResults | Select-Object Path,SignatureStatus,SignatureMessage,ChainOk | Format-List
 if (-not $result.AllSignaturesValid) { throw 'One or more Cinebench signatures remain invalid after certificate installation.' }
} finally {
 Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
}
